package com.tnc.tnc.arcana;
import com.tnc.tnc.life.routes.*;
import com.tnc.tnc.adventure.AdventureGameTests;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.Level;
import net.minecraftforge.gametest.*;
import java.util.*;
@GameTestHolder("tncarcana") @PrefixGameTestTemplate(false)
public final class TechnologyGameTests {
    private static void eatPrepared(ServerPlayer p){for(var meal:p.getInventory().items)if(meal.getItem() instanceof ArcanaMealItem){meal.finishUsingItem(p.level(),p);return;}throw new IllegalStateException("No portable meal was produced");}
    private static RouteNodeEntity node(ServerLevel l,BlockPos at,RouteKind kind,UUID owner){l.setBlock(at,RouteContent.NODES.get(kind.id).get().defaultBlockState(),3);var n=(RouteNodeEntity)l.getBlockEntity(at);n.owner=owner;return n;}
    private static RouteNodeEntity node(GameTestHelper h,int x,RouteKind kind,UUID owner){return node(h.getLevel(),h.absolutePos(new BlockPos(x,2,2)),kind,owner);}
    private static void shell(RouteNodeEntity n){for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)for(int y=0;y<3;y++)if(x!=0||z!=0)n.getLevel().setBlock(n.getBlockPos().offset(x,y,z),ArcanaContent.TOWER_BRICK.defaultBlockState(),3);}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void extractorConsumesOnceAndStopsForFullOutput(GameTestHelper h){var n=node(h,2,RouteKind.EXTRACTOR,UUID.randomUUID());n.mana=60;n.inventory.setItem(0,new ItemStack(ArcanaContent.item("stone_pattern_leaf"),2));for(int i=0;i<3;i++)ArcanaTechnology.tick(h.getLevel(),n);h.assertTrue(n.mana==45&&n.inventory.getItem(0).getCount()==1&&n.inventory.getItem(4).is(ArcanaContent.item("mana_root_core")),"one real herb and15M become one root core");n.inventory.setItem(4,new ItemStack(Items.STONE,64));for(int i=0;i<10;i++)ArcanaTechnology.tick(h.getLevel(),n);h.assertTrue(n.mana==45&&n.inventory.getItem(0).getCount()==1,"blocked output consumes nothing");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void igniterTapsActualSharedPotAndDebitsFive(GameTestHelper h){var p=AdventureGameTests.player(h);var at=h.absolutePos(new BlockPos(3,2,3));h.getLevel().setBlock(at,com.tnc.tnc.alchemy.AlchemyContent.CAULDRON.defaultBlockState(),3);var pot=(com.tnc.tnc.alchemy.AlchemyEntity)h.getLevel().getBlockEntity(at);pot.owner=p.getUUID();pot.addWater();var n=node(h.getLevel(),at.west(),RouteKind.IGNITER,p.getUUID());n.mana=10;p.teleportTo(at.getX(),at.getY(),at.getZ());h.assertTrue(ArcanaTechnology.heat(p,n,true)&&pot.temperature==60&&pot.hasIgnited&&n.mana==5,"tap is real magic heat +60 for5M");h.assertTrue(!ArcanaTechnology.heat(p,n,true)&&n.mana==5,"held-click packet spam is rate limited");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void phaseFilteringPreservesAmountsAndRejectsWrongNurture(GameTestHelper h){UUID owner=UUID.randomUUID();var source=node(h,1,RouteKind.LUNAR,owner);var phase=node(h,2,RouteKind.PHASE_SHIFTER,owner);var altar=node(h,3,RouteKind.NURTURE,owner);source.receive(500);ArcanaEnergy.credit(source,"lunar",300);ArcanaEnergy.credit(source,"water",200);phase.inventory.setItem(0,new ItemStack(Items.MAGMA_CREAM));altar.inventory.setItem(0,new ItemStack(ArcanaContent.item("fire_wand_3")));
        h.assertTrue(ArcanaEnergy.move(source,phase,500)==300&&source.mana==200,"phase rejects already elemental input");ArcanaTechnology.phase(phase);h.assertTrue(phase.mana==300&&ArcanaEnergy.amount(phase,"fire")==256&&ArcanaEnergy.amount(phase,"lunar")==44&&phase.inventory.getItem(0).getCount()==1,"256M/s retyping never adds balance or consumes filter");h.assertTrue(ArcanaEnergy.move(phase,altar,256)==256&&phase.mana==44,"only converted fire enters altar");ArcanaDevices.tick(h.getLevel(),altar);h.assertTrue(altar.mana==0&&altar.inventory.getItem(0).getTag().getInt("SpiritMana")==256,"same-source mana goes into actual wand");h.assertTrue(ArcanaEnergy.move(source,altar,200)==0&&source.mana==200,"water cannot feed fire wand");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void breakthroughNeedsTenThousandAndActualCore(GameTestHelper h){var p=AdventureGameTests.player(h);var n=node(h,2,RouteKind.NURTURE,p.getUUID());n.inventory.setItem(0,new ItemStack(ArcanaContent.item("lightning_wand_3")));var core=new ItemStack(Items.NETHER_STAR);h.assertTrue(!ArcanaDevices.breakthrough(p,n,core)&&core.getCount()==1,"early core is retained");n.inventory.getItem(0).getOrCreateTag().putInt("SpiritMana",10000);h.assertTrue(ArcanaDevices.breakthrough(p,n,core)&&core.isEmpty()&&n.inventory.getItem(0).getTag().getString("SpiritAffix").equals("element_lightning"),"real core consumed for lightning-exclusive awakening");h.assertTrue(!ArcanaDevices.breakthrough(p,n,new ItemStack(Items.NETHER_STAR)),"same wand cannot breakthrough twice");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void twoFoodsGiveDailyBenefitAndMasterHasNoToxicity(GameTestHelper h){var p=AdventureGameTests.player(h);var n=node(h,2,RouteKind.MEAL_PLATE,p.getUUID());n.inventory.setItem(0,new ItemStack(Items.SUGAR));n.inventory.setItem(1,new ItemStack(Items.COOKED_BEEF));p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);ArcanaMeals.interact(p,n,InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(n.getBlockPos()),Direction.UP,n.getBlockPos(),false));h.assertTrue(!p.hasEffect(ArcanaMealEffects.MEALS[0]),"preparing meal does not eat it");eatPrepared(p);h.assertTrue(p.hasEffect(ArcanaMealEffects.MEALS[0])&&n.inventory.isEmpty()&&ArcanaPhysiology.data(p).getLong("MealSunUntil")==0,"two adjacent tastes make everyday buff, not just ultimate dish");ArcanaPhysiology.drink(p,RitualRules.Quality.MASTER);h.assertTrue(ArcanaPhysiology.toxicity(p)==0,"master toxicity is exactly zero");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void nineTastesSunLastsExactlyThreeMinutes(GameTestHelper h){var p=AdventureGameTests.player(h);var n=node(h,2,RouteKind.MEAL_PLATE,p.getUUID());String[] items={"hearth_pepper_fruit","dance_petal","rainletter_berry","stone_pattern_leaf","homeward_flower_petal","rainletter_berry","star_dew_fruit","mana_root_core","steam_lotus_heart"};for(int i=0;i<9;i++)n.inventory.setItem(i,new ItemStack(ArcanaContent.item(items[i])));h.assertTrue(ArcanaMeals.active(n),"five tastes with sufficient harmonious edges form a sun");p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);ArcanaMeals.interact(p,n,InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(n.getBlockPos()),Direction.UP,n.getBlockPos(),false));eatPrepared(p);h.assertTrue(ArcanaPhysiology.data(p).getLong("MealSunUntil")==ArcanaPhysiology.now(p)+3600,"actual persistent benefit lasts3600ticks");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void conflictingFoodReallyPreventsSpellCasting(GameTestHelper h){var p=AdventureGameTests.player(h);var n=node(h,2,RouteKind.MEAL_PLATE,p.getUUID());n.inventory.setItem(0,new ItemStack(Items.SUGAR));n.inventory.setItem(1,new ItemStack(Items.POTATO));p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);ArcanaMeals.interact(p,n,InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(n.getBlockPos()),Direction.UP,n.getBlockPos(),false));eatPrepared(p);h.assertTrue(p.hasEffect(ArcanaMealEffects.NO_MAGIC)&&com.tnc.tnc.magic.ManaGate.shouldBlock(p,net.minecraft.resources.ResourceLocation.parse("tnc:water_ball")),"wind/earth clash grants real15-second cast lock");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void emptyCompassDoesNotChargeForDestroyedTargets(GameTestHelper h){var p=AdventureGameTests.player(h);var n=node(h,2,RouteKind.LEYLINE_COMPASS,p.getUUID());n.mana=400;var at=h.absolutePos(new BlockPos(5,2,5));LeylineDiscoveries.add(h.getLevel(),at);h.getLevel().setBlock(at,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);h.assertTrue(!LeylineDiscoveries.activate(p,n)&&n.mana==400,"stale loaded target is pruned before charging200M");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void towerFlashChargeDebitsRealTwelveThousand(GameTestHelper h){var p=AdventureGameTests.player(h);var tower=node(h,3,RouteKind.ABYSS_TOWER,p.getUUID());shell(tower);tower.receive(20000);var charger=node(h.getLevel(),tower.getBlockPos().offset(2,0,0),RouteKind.CHARGER,p.getUUID());var mech=new ItemStack(RouteContent.item("mana_mech"));charger.inventory.setItem(0,mech);h.runAfterDelay(20-h.getLevel().getGameTime()%20,()->{RouteNodeEntity.tick(h.getLevel(),charger.getBlockPos(),charger);h.assertTrue(RouteChargeLedger.get(h.getLevel()).amount(mech)==12000&&tower.mana+charger.mana==8000,"tower pays actual charge without fictitious800M buffer");h.succeed();});}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void billionCoreHasNoHiddenInfiniteBalance(GameTestHelper h){var n=node(h,2,RouteKind.SINGULARITY,UUID.randomUUID());n.receive(2000000000);n.getPersistentData().putLong("SingularityBalance",Long.MAX_VALUE);ArcanaDevices.tick(h.getLevel(),n);h.assertTrue(n.mana==2000000000&&n.receive(1)==0&&!n.getPersistentData().contains("SingularityBalance"),"honest two-billion capacity, no hidden unlimited stash");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=100) public static void crossDimensionOasisPaysMaintenanceAndUnlinks(GameTestHelper h){var p=AdventureGameTests.player(h);var l=h.getLevel();var tower=node(h,3,RouteKind.ABYSS_TOWER,p.getUUID());shell(tower);tower.receive(5000);var origin=node(l,tower.getBlockPos().offset(2,0,0),RouteKind.DIMENSION_PRISM,p.getUUID());var nether=p.server.getLevel(Level.NETHER);h.assertTrue(nether!=null,"actual Nether exists");if(nether==null)return;var at=new BlockPos(origin.getBlockPos().getX(),100,origin.getBlockPos().getZ());nether.getChunkAt(at);var dest=node(nether,at,RouteKind.DIMENSION_PRISM,p.getUUID());
        h.assertTrue(!ArcanaRealms.powered(nether,at)&&!RoutePlanting.grow(RouteContent.PLANTS.get(NewPlantKind.STEAM.id).get().defaultBlockState(),nether,at.above()),"barren Nether has no natural planting/growth before power");String error=ArcanaRealms.link(p,GlobalPos.of(l.dimension(),origin.getBlockPos()),GlobalPos.of(nether.dimension(),at));h.assertTrue(error.isEmpty(),"real two-dimension pair links: "+error);ArcanaRealms.pump(p.server);h.assertTrue(tower.mana==804&&dest.mana==4096&&ArcanaRealms.powered(nether,at.offset(47,0,0))&&!ArcanaRealms.powered(nether,at.offset(49,0,0)),"100M maintenance plus4096M transport conserves balance and activates only48radius");
        tower.extract(tower.mana);ArcanaRealms.pump(p.server);h.assertTrue(!ArcanaRealms.powered(nether,at),"empty tower disables the oasis despite stocked endpoint");RouteMirrorLinks.unlink(l,origin);h.assertTrue(dest.mirrorTarget==null&&origin.mirrorTarget==null,"unlink clears both dimensions and tickets");nether.removeBlock(at,false);h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void sponsorPaysOnlyActualReleasedHighTierSpell(GameTestHelper h){var p=AdventureGameTests.player(h);var tower=node(h,3,RouteKind.ABYSS_TOWER,p.getUUID());shell(tower);tower.receive(500);p.teleportTo(tower.getBlockPos().getX(),tower.getBlockPos().getY(),tower.getBlockPos().getZ()+2);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ArcanaContent.item("fire_wand_3")));var spell=com.tnc.tnc.magic.SpellCatalog.all().stream().filter(e->e.element()==com.tnc.tnc.magic.Element.FIRE&&e.tier()==3).findFirst().orElseThrow();int cost=com.tnc.tnc.equipment.MageGear.spellCost(p,spell.manaCostFor(com.tnc.tnc.magic.MagicStone.getOrNull(p).getMaxMana()));h.assertTrue(ArcanaBeacon.affordable(p,spell,cost)&&tower.mana==500,"eligibility does not pre-charge");ArcanaBeacon.enter(p,spell.id(),true);ArcanaBeacon.provision(p);h.assertTrue(ArcanaBeacon.reserved(tower)==cost&&tower.extract(500)==500-cost,"held spell mana cannot be stolen");tower.receive(500-cost);h.assertTrue(ArcanaBeacon.pay(p,spell,cost)&&tower.mana==500-cost&&ArcanaBeacon.scale(p)==1.5f,"successful release pays once");h.assertTrue(ArcanaBeacon.pay(p,spell,cost)&&tower.mana==500-cost,"duplicate success callback cannot double-charge");ArcanaBeacon.leave(p);h.assertTrue(ArcanaBeacon.scale(p)==1&&ArcanaBeacon.reserved(tower)==0,"no persistent free boost after cast returns");ArcanaBeacon.enter(p,spell.id(),true);ArcanaBeacon.provision(p);int balance=tower.mana;ArcanaBeacon.leave(p);h.assertTrue(tower.mana==balance&&ArcanaBeacon.reserved(tower)==0,"failed/no-target call releases escrow without charging");h.succeed();}

}
